		db.Node("heard");
		db.Public();
		db.Say("", "\"Somebody. Somebody's there. I'll keep this on. I'll call again at dusk, if you'll listen.\"");
		db.Do("cset:opening.answered=1");
		db.Choice("dusk", "\"I'll listen at dusk.\"", "hub", "", "", "", "", "", "", "", "");
